definition.raw:
An {\itshape $\mathcal{H}$-polyhedron} is an intersection of finitely many
closed halfspaces in some $\mathbb R^d$. An {\itshape $\mathcal{H}$-polytope}
is a bounded $\mathcal{H}$-polyhedron.

For two polytopes
\begin{gather*}
P^{n_1}=\{\ib{x}\in\mathbb R^{n_1}:\;\langle
\ib{a}_i,\ib{x}\rangle+1\geqslant 0,\;i=1,\dots,m_1\},\\
Q^{n_2}=\{\ib{y}\in\mathbb R^{n_2}:\;\langle
\ib{b}_j,\ib{y}\rangle+1\geqslant 0,\;j=1,\dots,m_2\}
\end{gather*}
let us define the polytope
$$
P^{n_1}\circ Q^{n_2}=\conv(P^{n_1}\times\{\mathbf 0\}\cup\{\mathbf 0\}\times Q^{n_2})\subset\mathbb R^{n_1}\times\mathbb R^{n_2}
$$

For the ring $\mathcal{RP}$ let us define an {\itshape $\alpha$-character}
$\varepsilon_{\alpha}$ by the formula
$$
\varepsilon_{\alpha}(P^n)=\alpha^{n+1}=\alpha^{\rho (P)}
$$
Then $\varepsilon_{0}$ is the counit $\varepsilon$.

The correspondence $P\to\ BP$ defines a linear {\itshape bipyramid operator}
of degree $+2$ on the rings $\mathcal{P}$ and $\mathcal{RP}$. By definition
$B\varnothing=\pt$.

theorem.raw:
Let $P^n$ be an $n$-dimensional polytope, and $S\subset\{0,\dots,n-1\}$. If
$\{i,k\}\subseteq S\cup\{-1,n\}$ such that $i<k-1$ and
$S\cap\{i+1,\dots,k-1\}=\varnothing$, then
\begin{equation}\label{BBR}
\sum\limits_{j=i+1}^{k-1}(-1)^{j-i-1}f_{S\cup\{j\}}=(1-(-1)^{k-i-1})f_S.
\end{equation}

The image of the space $\mathcal{P}^{2n}$ generated by all
$n$-dimensional polytopes in the ring\linebreak
$\Qsym[t_1,\dots,t_r][\alpha],\;r\geqslant n$ under the mapping $f_r$
consists of all the homogeneous polynomials $g$ of degree $2n$  satisfying
the equations
\begin{enumerate}
\item
\begin{align*}
g(\alpha,t_1,-t_1,t_3,\dots,t_r)&=g(\alpha,0,0,t_3,\dots,t_r);\\
g(\alpha,t_1,t_2,-t_2,t_4,\dots,t_r)&=g(\alpha,t_1,0,0,t_4\dots,t_r);\\
\dots\\
g(\alpha,t_1,\dots,t_{r-2},t_{r-1},-t_{r-1})&=g(\alpha,t_1,\dots,t_{r-2},0,0);
\end{align*}
\item
$$
g(-\alpha,t_1,\dots,t_{r-1},\alpha)=g(\alpha,t_1,\dots,t_{r-1},0);
$$
\end{enumerate}
These equations are equivalent to the Bayer-Billera (generalized
Dehn-Sommerville) relations.\label{f}

Let $\psi:\mathcal{P}\to\Qsym[t_1,t_2,\dots][\alpha]$ be a linear map such
that
\begin{enumerate}
\item $\psi(\alpha,0,0,\dots)(P^n)=\alpha^n$;
\item The following diagram commutes:

$$
\begin{CD}
\mathcal{P} @>\psi>>\Qsym[t_1,t_2,\dots][\alpha]\\
@V{\Phi}VV @VTVV\\
\mathcal{P}[t]@>\psi>>\Qsym[t,t_1,t_2,\dots][\alpha]
\end{CD}
$$
\end{enumerate}
Then $\psi=f$.

\begin{itemize}
\item For $r\geqslant n$ the image
    $f_r(\mathcal{P}^{2n})\subset\Qsym[t_1,\dots,t_r][\alpha]$ consists
    of homogeneous polynomials $g$ of degree $2n$ satisfying the
    equations
\begin{enumerate}
\item
\begin{equation}\label{I}
\begin{aligned}
g(\alpha,t_1,-t_1,t_3,\dots,t_r)&=g(\alpha,0,0,t_3,\dots,t_r)\\
g(\alpha,t_1,t_2,-t_2,\dots,t_r)&=g(\alpha,t_1,0,0,\dots,t_r)\\
\dots \\
g(\alpha,t_1,\dots,t_{r-1},-t_{r-1})&=g(\alpha,t_1,\dots,0,0)
\end{aligned}
\end{equation}
\item
\begin{equation}\label{I2}
g(-\alpha,t_1,t_2,\dots,t_{r-1},\alpha)=g(\alpha,t_1,t_2,\dots,t_{r-1},0)
\end{equation}
\end{enumerate}
\item For $r\geqslant n$ the image
    $f_{\mathcal{RP},\,r}(\mathcal{RP}^{2n})\subset\Qsym[t_1,\dots,t_r][\alpha]$
    consists of homogeneous polynomials $g$ of degree $2n$ satisfying the
    following conditions:
\begin{enumerate}
\item The equations of type (\ref{I})
\item The equation
$$
g(-\alpha,t_1,t_2,\dots,t_{r-1},\alpha)=g(0,t_1,t_2,\dots,t_{r-1},0)
$$
\end{enumerate}
\item For $r\geqslant n$ the image
    $\F_r(\mathcal{RP}^{2n})\subset\Qsym[t_1,\dots,t_r]$ consists of
    homogeneous polynomials $g$ of degree $2n$ satisfying the equations
    of type (\ref{I}).
\end{itemize}
In all the cases the equations are equivalent to the Bayer-Billera
(generalized Dehn-Sommerville) relations \cite{BB}

lemma.raw:
Let $D\in\mathcal{D}(\R)$ be an operator of graduation $2k$. Then for each
space $\R^{2n},\;n\geqslant k$ there is a unique representation
\begin{equation}\label{X5}
D=u(d_2,d_3,\dots,d_k)+dw(d_2,d_3,\dots,d_{k-1}),
\end{equation}
and there is a unique representation
\begin{equation}\label{X6}
D=u'(d_2,d_3,\dots,d_k)+w'(d_2,\dots,d_{k-1})d,
\end{equation}
where $u,u',w,w'$ are polynomials.\label{basis}

