\section{Structure theorems}
\begin{prop}
$\mathcal{P}$ is a polynomial ring generated by indecomposable combinatorial
polytopes.
\end{prop}
\begin{proof}
We will show that any polytope $P^n$ of positive dimension can be represented
in a unique up to the order of factors way as a product of indecomposable
polytopes of positive dimensions $P=P_1\times\dots\times P_k$.

Natural Hopf comodule structure
$\mathcal{P}$ is not a Hopf algebra, but it turns out that there is a natural
Hopf comodule structure on the ring $\mathcal{P}$ over the Hopf algebra
$\mathcal{RP}$.

\begin{prop}
Formula
$$
\Delta_{\mathcal{RP}} P=\sum\limits_{F\subseteq P}F\otimes(P/F)
$$
defines a natural graded right Hopf comodule structure
$\Delta_{\mathcal{RP}}\colon\mathcal{P}\to\mathcal{P}\otimes\mathcal{RP}$ on
the ring $\mathcal{P}$ over the Hopf algebra $\mathcal{RP}$.
\end{prop}
\begin{proof}
We should proof that the following two diagrams commute
$$
\xymatrix{
\mathcal{P}\ar[d]^{\Delta_{\mathcal{RP}}}\ar[rr]^{\Delta_{\mathcal{RP}}}&&\mathcal{P}\otimes\mathcal{RP}\ar[d]^{\id\otimes\Delta}\\
\mathcal{P}\otimes\mathcal{RP}\ar[rr]^{\Delta_{\mathcal{RP}}\otimes\id}&&\mathcal{P}\otimes\mathcal{RP}\otimes\mathcal{RP}\\
}
\hspace{2cm}
\xymatrix{
\mathcal{P}\ar[d]_{\Delta_{\mathcal{RP}}}\ar[dr]^{\id\otimes 1}&\\
\mathcal{P}\otimes \mathcal{RP}\ar[r]^{\id\otimes \varepsilon}&\mathcal{P}\otimes\mathbb Z\\
}
$$
and that $\Delta_{\mathcal{RP}}$ is a ring homomorphism. Indeed, we have
\begin{multline*}
(\Delta_{\mathcal{RP}}\otimes\id)\circ\Delta_{\mathcal{RP}} P=(\Delta_{\mathcal{RP}}\otimes\id)\left(\sum\limits_{F\subseteq P}F\otimes P/F\right)=\sum\limits_{F\subseteq P}\left(\sum\limits_{G\subseteq F}G\otimes F/G\right)\otimes P/F=\\
=\sum\limits_{G\subseteq P}G\otimes\left(\sum\limits_{G\subseteq F\subseteq
P}F/G\otimes P/F\right)=\sum\limits_{G\subseteq P}G\otimes\Delta (P/G)
=(\id\otimes\Delta)\circ\Delta_{\mathcal{RP}} P,
\end{multline*}
and
$$ (\id\otimes\varepsilon)\circ\Delta_{\mathcal{RP}}(P)=\sum\limits_{F\subseteq
P}F\otimes\varepsilon(P/F)=P\otimes 1,
$$

Let us check that $\Delta_{\mathcal{RP}}$ is a homomorphism of rings
$\mathcal{P}\to\mathcal{P}\otimes\mathcal{RP}$:
\begin{multline*}
\Delta_{\mathcal{RP}}(P\times Q)=\sum\limits_{F\times G\subseteq P\times
Q}(F\times G)\otimes \left(P\times Q/ F\times G\right)=
\sum\limits_{F\subseteq P,\,G\subseteq Q}(F\times G)\otimes \left(P/F\divideontimes Q/G\right)=\\
=\left(\sum\limits_{F\subseteq P}F\otimes
P/F\right)\cdot\left(\sum\limits_{G\subseteq Q}G\otimes
Q/G\right)=\Delta_{\mathcal{RP}}(P)\cdot\Delta_{\mathcal{RP}}(Q)
\end{multline*}
$$
\Delta_{\mathcal{RP}}(\pt)=\pt\otimes (\pt/\pt)=\pt\otimes \varnothing=1\otimes 1.
$$
\end{proof}

\begin{cor}
\begin{itemize}
\item Any ring homomorphism $\mathcal{P}\to\mathcal{A}$, where
    $\mathcal{A}$ is a ring, induces the ring homomorphism
    $\mathcal{P}\to\mathcal{A}\otimes\mathcal{RP}$
\item Any linear homomorphism $\psi\colon\mathcal{RP}\to\mathbb Z$
    induces the linear operator $\mathcal{P}\to\mathcal{P}$, which is a
    ring homomorphism, if $\psi$ is a ring homomorphism.
\end{itemize}
\end{cor}

